document.addEventListener('DOMContentLoaded', () => { const alphabet = 'ABCDEFGHJKLMNPQRSTUVWXYZabcdefghijkmnopqrstuvwxyz23456789!@#$%&*?'; const pick = (chars) => chars[Math.floor(Math.random() * chars.length)]; const shuffle = (value) => value.split('').sort(() => Math.random() - 0.5).join(''); document.querySelectorAll('.js-toggle-password').forEach((button) => { button.addEventListener('click', () => { const input = document.querySelector(button.dataset.target || ''); if (!input) return; const show = input.type === 'password'; input.type = show ? 'text' : 'password'; button.querySelector('i')?.classList.toggle('fa-eye', !show); button.querySelector('i')?.classList.toggle('fa-eye-slash', show); }); }); document.querySelector('.js-generate-password')?.addEventListener('click', () => { const passwordInput = document.querySelector('.js-profile-password'); const confirmationInput = document.querySelector('.js-profile-password-confirmation'); if (!passwordInput || !confirmationInput) return; let password = [ pick('ABCDEFGHJKLMNPQRSTUVWXYZ'), pick('abcdefghijkmnopqrstuvwxyz'), pick('23456789'), pick('!@#$%&*?'), ].join(''); while (password.length < 16) { password += pick(alphabet); } password = shuffle(password); passwordInput.value = password; confirmationInput.value = password; passwordInput.type = 'text'; confirmationInput.type = 'text'; passwordInput.dispatchEvent(new Event('input', { bubbles: true })); }); });